CREATE TABLE campuses(id BIGINT PRIMARY KEY,name VARCHAR(128),code VARCHAR(64) UNIQUE,status VARCHAR(32),deleted_at TIMESTAMP);
CREATE TABLE users(id BIGINT PRIMARY KEY,campus_id BIGINT,nickname VARCHAR(64),avatar_url VARCHAR(512),avatar_attachment_id BIGINT,status VARCHAR(32),version INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP,deleted_at TIMESTAMP);
CREATE TABLE campus_regions(id BIGINT PRIMARY KEY,campus_id BIGINT,parent_id BIGINT,name VARCHAR(128),type VARCHAR(32),status VARCHAR(32),deleted_at TIMESTAMP);
CREATE TABLE campus_organizations(id BIGINT PRIMARY KEY,campus_id BIGINT,name VARCHAR(128),type VARCHAR(32),status VARCHAR(32),deleted_at TIMESTAMP);
CREATE TABLE campus_configs(id BIGINT PRIMARY KEY,campus_id BIGINT,config_key VARCHAR(128),config_value VARCHAR(4000));
CREATE TABLE user_wechat_identities(id BIGINT PRIMARY KEY,user_id BIGINT,app_id VARCHAR(64),openid VARCHAR(128),unionid VARCHAR(128),created_at TIMESTAMP,UNIQUE(app_id,openid));
CREATE TABLE user_phones(id BIGINT PRIMARY KEY,user_id BIGINT,phone_encrypted VARBINARY(255),phone_search CHAR(64) UNIQUE,verified INT,created_at TIMESTAMP,verified_user_id BIGINT GENERATED ALWAYS AS (CASE WHEN verified=1 THEN user_id ELSE NULL END),UNIQUE(verified_user_id));
CREATE TABLE authorizations(id BIGINT PRIMARY KEY,user_id BIGINT,type VARCHAR(32),scope VARCHAR(128),status VARCHAR(32),version INT DEFAULT 0,granted_at TIMESTAMP,revoked_at TIMESTAMP,created_at TIMESTAMP);
CREATE TABLE student_verifications(id BIGINT PRIMARY KEY,user_id BIGINT,campus_id BIGINT,student_id_encrypted VARBINARY(255),student_id_search CHAR(64),status VARCHAR(32),verified_at TIMESTAMP,reviewer_id BIGINT,reject_reason VARCHAR(255),version INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP,verified_search CHAR(64) GENERATED ALWAYS AS(CASE WHEN status='verified' THEN student_id_search ELSE NULL END),active_user BIGINT GENERATED ALWAYS AS(CASE WHEN status IN ('pending','verified') THEN user_id ELSE NULL END),UNIQUE(campus_id,verified_search),UNIQUE(active_user));
CREATE TABLE user_profiles(id BIGINT PRIMARY KEY,user_id BIGINT UNIQUE,college VARCHAR(128),grade VARCHAR(32),skills VARCHAR(4000),interests VARCHAR(4000),version INT,created_at TIMESTAMP,updated_at TIMESTAMP);
CREATE TABLE roles(id BIGINT PRIMARY KEY,code VARCHAR(64) UNIQUE,name VARCHAR(64),created_at TIMESTAMP);
CREATE TABLE user_roles(id BIGINT PRIMARY KEY,user_id BIGINT,role_id BIGINT,campus_id BIGINT,created_at TIMESTAMP,UNIQUE(user_id,role_id,campus_id));
CREATE TABLE admin_credentials(user_id BIGINT PRIMARY KEY,username VARCHAR(64) UNIQUE,password_hash VARCHAR(100),mfa_seed_encrypted VARBINARY(255),last_totp_step BIGINT DEFAULT -1,active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP);
CREATE TABLE student_roster(id BIGINT PRIMARY KEY,campus_id BIGINT,student_id_search CHAR(64),student_id_encrypted VARBINARY(255),college_encrypted VARBINARY(512),grade_encrypted VARBINARY(255),status VARCHAR(32),import_job_id BIGINT,created_at TIMESTAMP,UNIQUE(campus_id,student_id_search));
CREATE TABLE admin_audit_logs(id BIGINT PRIMARY KEY,operator_id BIGINT,action VARCHAR(64),target_type VARCHAR(32),target_id BIGINT,reason VARCHAR(512),detail_json VARCHAR(4000),created_at TIMESTAMP);
CREATE TABLE async_jobs(id BIGINT PRIMARY KEY,job_type VARCHAR(64),payload_json VARCHAR(4000),status VARCHAR(32),result_json VARCHAR(4000),created_at TIMESTAMP,updated_at TIMESTAMP,campus_id BIGINT,owner_user_id BIGINT,access_domain VARCHAR(32),retry_count INT DEFAULT 0,max_retries INT DEFAULT 3,next_retry_at TIMESTAMP,picked_at TIMESTAMP,claim_token VARCHAR(64),error VARCHAR(1024));
CREATE TABLE api_idempotency_records(id BIGINT PRIMARY KEY,campus_id BIGINT,user_id BIGINT,scope_digest CHAR(64),key_digest CHAR(64),request_digest CHAR(64),response_encrypted BLOB,response_type VARCHAR(255),status VARCHAR(16),created_at TIMESTAMP,expires_at TIMESTAMP,UNIQUE(scope_digest,key_digest));
